import{_ as r,o,c as a,a0 as s}from"./chunks/framework.jwovEGr5.js";const p=JSON.parse('{"title":"ADR 0001 — Eval surface scope for sharecli (Harbor / SWE-bench out of scope)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-eval-surface-out-of-scope.md","filePath":"adr/0002-eval-surface-out-of-scope.md"}'),t={name:"adr/0002-eval-surface-out-of-scope.md"};function n(i,e,c,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0001-—-eval-surface-scope-for-sharecli-harbor-swe-bench-out-of-scope" tabindex="-1">ADR 0001 — Eval surface scope for sharecli (Harbor / SWE-bench out of scope) <a class="header-anchor" href="#adr-0001-—-eval-surface-scope-for-sharecli-harbor-swe-bench-out-of-scope" aria-label="Permalink to &quot;ADR 0001 — Eval surface scope for sharecli (Harbor / SWE-bench out of scope)&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-07-10<br><strong>Deciders:</strong> sharecli maintainers<br><strong>Supersedes:</strong> —<br><strong>Traceability:</strong> audit-v38 C08 (L71–L80), <code>docs/eval/REPRO.md</code></p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>audit-v38 cluster <strong>C08 Eval Coverage</strong> scores agent-eval frameworks (Harbor / Terminal-Bench, SWE-bench / SWE-RL), cross-language parity harnesses, compression benches, and LLM token-burn tracking alongside ordinary Criterion / load benches.</p><p>sharecli is a <strong>local process supervisor / CLI daemon</strong> (spawn, pool, health, serve, cast). It is not an agent-eval product, a coding-agent benchmark runner, or an LLM gateway. Treating missing Harbor/SWE-bench wiring as a product defect mis-scores the repo against the wrong profile.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>In scope (process-supervisor eval):</strong> Criterion microbenches under <code>benches/</code>, load scripts under <code>scripts/load/</code>, reproducibility contract in <code>docs/eval/REPRO.md</code>, soft CI in <code>.github/workflows/bench.yml</code>, and SLO rows in <code>docs/ops/SLO.md</code> that link those benches.</li><li><strong>Out of scope (explicit N/A until product scope expands):</strong><ul><li>Harbor / portage / Terminal-Bench agent-eval pipelines (<strong>L76</strong>)</li><li>SWE-bench / SWE-RL task corpora (<strong>L71</strong> agent-task families)</li><li>Cross-language (Py/Go/TS) eval parity suites (<strong>L75</strong>)</li><li>Compression / spec-extraction benchmark suites (<strong>L77</strong>)</li><li>Per-eval LLM cost / token-burn tracking (<strong>L78</strong>)</li></ul></li><li><strong>Governance:</strong> This ADR is the eval policy for sharecli (<strong>L80</strong>). Revisit only if sharecli claims an agent-eval or multi-lang harness product surface.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Auditors should score L75–L78 as <strong>N/A / deferred</strong> (or seeded-only via this ADR), not as absent product gaps.</li><li>C08 lifts come from Criterion + load + REPRO + soft bench workflow + this ADR, not from adopting Harbor.</li><li>If a future FR requires agent-eval, supersede this ADR and wire Harbor in a dedicated crate/repo rather than bloating the supervisor binary.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Rubric: <code>audit/rubric/audit-30-pillar/audit-30-pillar-L71-L80-eval-coverage.md</code></li><li>Lane baseline: <code>audit/.lane-c08/C08.md</code> (pre-remediation 0/30 F)</li><li>Repro contract: <a href="./../eval/REPRO.html"><code>../eval/REPRO.md</code></a></li></ul>',12)])])}const g=r(t,[["render",n]]);export{p as __pageData,g as default};
